let uidCounter = 0;
function scopeSvgIds(svg: string, prefix = "pf" + (++uidCounter)): string {
  return svg.replace(/(\bid="|url\(#|href="#)([\w-]+)/g, (_m, p1, id) => p1 + id + "-" + prefix);
}

export function getPenSvg(pen: PenId, style: PenStyle = "real", ink: InkColor = "blue", withShadow = true): string {
  const spec = pw[pen];
  if (style === "blueprint") {
    const len = spec.length * 20;
    const h = Math.max(16, spec.width * 22);
    const halfH = h / 2;
    const strokeCol = ink === "violet" ? "#c4b5fd" : ink === "green" ? "#6ee7b7" : "#67e8f9";
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-12 -46 ${len + 24} 92" class="blueprint-pen" aria-hidden="true" focusable="false">
      <rect x="4" y="${-halfH}" width="${len - 28}" height="${h}" rx="${Math.min(8, halfH)}" fill="rgba(14, 116, 144, 0.28)" stroke="${strokeCol}" stroke-width="2.5"/>
      <path d="M${len - 24} ${-halfH} L${len} 0 L${len - 24} ${halfH} Z" fill="rgba(229, 169, 60, 0.35)" stroke="#f4cf5a" stroke-width="2.5"/>
      <line x1="0" y1="0" x2="${len}" y2="0" stroke="${strokeCol}" stroke-width="1.2" stroke-dasharray="5 4" opacity="0.8"/>
      <line x1="${len * 0.5}" y1="${-halfH - 8}" x2="${len * 0.5}" y2="${halfH + 8}" stroke="#f4cf5a" stroke-width="1.5"/>
      <circle cx="${len * 0.5}" cy="0" r="4.5" fill="none" stroke="#f4cf5a" stroke-width="1.8"/>
      <text x="${len * 0.22}" y="-3" fill="#e0f2fe" font-size="8.5" font-family="monospace" font-weight="700" letter-spacing="1">NIB&amp;KNOCK // ${pen.toUpperCase()}</text>
    </svg>`;
  }
  if (style === "classic") {
    const len = spec.length * 20;
    const inner = YC[pen]();
    const shadow = withShadow
      ? `<ellipse cx="${len / 2}" cy="13" rx="${len / 2}" ry="13" fill="#2f3b4b" opacity="0.14"/>`
      : "";
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-8 -42 ${len + 16} 90" class="classic-pen" aria-hidden="true" focusable="false">${shadow}${inner}</svg>`;
  }
  const r = spec.length;
  const shadow = withShadow
    ? `<defs><filter id="sh" x="-20%" y="-200%" width="140%" height="500%"><feGaussianBlur stdDeviation="0.22"/></filter></defs><path d="${spec.hit}" transform="translate(0.09 0.3)" fill="#241408" fill-opacity="0.32" filter="url(#sh)"/>`
    : "";
  const body = (spec.inks[ink] || spec.inks.blue).replace(/DESK WARS/g, "NIB &amp; KNOCK");
  return scopeSvgIds(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="-0.4 -2.1 ${r + 0.8} 4.5" class="real-pen" aria-hidden="true" focusable="false">${shadow}${body}</svg>`);
}

